// recipe: console-authority
// args: name=s
// returns: ok, role, refused, reason, key, error, detail
//
// Asks the container's own ConsoleCommandAuthority whether a named command may run HERE, and what refusal it would give. The
// console's command list and its completion both filter through this predicate, so a zero-length list with a working /help means
// this is where the answer differs.
((System.Func<string>)(() => { var services = CasualtiesUnknownOnline.Runtime.CuoBootstrap.Services; if (services == null) { return "{\"ok\":false,\"error\":\"no-services\"}"; } var name = {{s:name}}; var asms = System.AppDomain.CurrentDomain.GetAssemblies(); var authorityType = (System.Type)null; var registryType = (System.Type)null; for (var i = 0; i < asms.Length; i++) { if (authorityType == null) { try { authorityType = asms[i].GetType("CasualtiesUnknownOnline.Runtime.Session.Commands.ConsoleCommandAuthority", false); } catch { authorityType = null; } } if (registryType == null) { try { registryType = asms[i].GetType("CasualtiesUnknownOnline.Runtime.Session.Commands.ConsoleCommandRegistry", false); } catch { registryType = null; } } } if (authorityType == null || registryType == null) { return "{\"ok\":false,\"error\":\"no-types\"}"; } var authority = services.GetService(authorityType); var registry = services.GetService(registryType); if (authority == null || registry == null) { return "{\"ok\":false,\"error\":\"no-services-resolved\"}"; } var allProperty = registryType.GetProperty("All"); var all = allProperty.GetValue(registry) as System.Collections.IEnumerable; var count = 0; var found = (object)null; if (all != null) { foreach (var command in all) { count++; var nameProperty = command.GetType().GetProperty("Name"); if (nameProperty != null && string.Equals(nameProperty.GetValue(command) as string, name, System.StringComparison.OrdinalIgnoreCase)) { found = command; } } } if (found == null) { return "{\"ok\":false,\"error\":\"command-not-registered\",\"detail\":\"registry holds " + count + " command(s)\"}"; } var mayRun = authorityType.GetMethod("MayRun", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public); var allowed = (bool)mayRun.Invoke(authority, new object[] { found }); var refusalMethod = authorityType.GetMethod("TryRefusal", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public); var refusal = refusalMethod.Invoke(authority, new object[] { found }); var text = ""; if (refusal != null) { var textProperty = refusal.GetType().GetProperty("Text"); if (textProperty != null) { text = textProperty.GetValue(refusal) as string; } } return "{\"ok\":true,\"registryCount\":" + count + ",\"mayRun\":" + (allowed ? "true" : "false") + ",\"refusal\":\"" + (text ?? "").Replace("\"", "'") + "\"}"; }))()